// Parse the [DECISION JSON] code block out of the card update body.
// monday-card.sh appends a section that looks like:
//   ...other text...
//   [DECISION JSON]
//   {"primary_lane":...,"draft":{...},...}

const payload = $input.first().json;
const body = payload?.data?.items?.[0]?.updates?.[0]?.body || '';

const marker = '[DECISION JSON]';
const idx = body.indexOf(marker);
if (idx === -1) {
  throw new Error('No [DECISION JSON] block found on this card. Update monday-card.sh to append the decision JSON.');
}
const jsonText = body.slice(idx + marker.length).trim();
// monday's update bodies sometimes wrap in HTML; strip simple tags.
const cleaned = jsonText.replace(/<[^>]+>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');

let decision;
try {
  decision = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Could not parse decision JSON: ' + e.message + '\nGot: ' + cleaned.slice(0, 200));
}

const pulseId = $('Monday Webhook').item.json.body.event.pulseId;
return [{ json: { decision, pulseId } }];
